#include <Arduino.h>

const int temperaturePin = A0;
const int fanPin = 5;

void setup() {
  pinMode(temperaturePin, INPUT);
  pinMode(fanPin, OUTPUT);
  analogWrite(fanPin, 0);
}

void loop() {
  int raw = analogRead(temperaturePin);
  float temperatureC = raw * (5.0f / 1023.0f) * 100.0f;
  analogWrite(fanPin, temperatureC > 30.0f ? 255 : 0);
  delay(20);
}
